import SwiftUI
import Symbols

/// An opaque luminance union: overlapping copies do not amplify transition alpha.
/// Convert the complete mask with luminanceToAlpha only after combining all role cutouts.
struct NativeSymbolClearance<Glyph:View>:View {
 var gap:CGSize
 var glyph:Glyph
 init(gap:CGSize,@ViewBuilder glyph:()->Glyph){self.gap=gap;self.glyph=glyph()}
 var body:some View {
  ZStack {
   Color.white
   glyph.foregroundStyle(.black).background(.white).compositingGroup().blendMode(.darken)
   ForEach(0..<16,id:\.self){i in
    let angle=CGFloat(i) * .pi/8
    glyph.foregroundStyle(.black).offset(x:gap.width*cos(angle),y:gap.height*sin(angle))
     .background(.white).compositingGroup().blendMode(.darken)
   }
  }.compositingGroup()
 }
}

/// Native SF Symbols composition. No custom drawing, path parser, raster glyphs or web renderer.
/// The gauge asset preserves Apple's original contours and Variable Draw keyframes.
@available(macOS 26.0, *)
public struct ComputeGauge: View {
 public enum Pace: String, CaseIterable, Codable { case normal, slow, fast, extreme }
 public enum Health: String, CaseIterable, Codable { case live, stale, unknown, paused, offline, outage, disabled, authentication }
 public enum Funding: String, CaseIterable, Codable { case subscription, paidEnabled, paidActive, creditAvailable, creditActive }
 public struct State: Equatable, Codable {
  /// One to three windows. Nil preserves the original weekly/session API.
  public var windows:[UsageWindow]?=nil
  public var provider="claudecode"
  public var weeklyUsed:Double?=0.64
  public var fiveHourUsed:Double?=0.38
  public var weeklyReset=ResetCountdown(units:7,secondsPerUnit:86400)
  public var fiveHourReset=ResetCountdown(units:5,secondsPerUnit:3600)
  public var pace:Pace = .normal
  /// Optional event time synchronizes multiple instances and makes snapshots deterministic.
  /// Leave nil to show a four-second notice automatically when pace changes.
  public var paceEventAt:Date?=nil
  public var health:Health = .live
  public var healthEventAt:Date?=nil
  public var funding:Funding = .subscription
  // Legacy bank inputs are ignored by the reset-time design.
  public var availableResets=2
  public var spentResets=2
  public var canReset=true
  public var recoveryAt:Date?=nil
  public var recoveryIsReliable=true
  public var accessibilityDescription=""
  public init(){}
 }
 public var state:State
 public var size:CGFloat
 public var weight:Font.Weight
 public var now:Date
 @SwiftUI.State private var automaticNotice=false
 @SwiftUI.State private var pixelOrigin:CGPoint = .zero
 @SwiftUI.State private var expiredPaceEvent:Date?=nil
 @Environment(\.accessibilityReduceMotion) private var reduceMotion
 @Environment(\.symbolMotionDuration) private var motionDuration
 @Environment(\.symbolInspectionScale) private var inspectionScale
 @Environment(\.gaugeCalibration) private var calibration
 @Environment(\.displayScale) private var displayScale
 @Environment(\.computeGaugeLayout) private var variation
 private var pair:GaugeCalibration.Pair{calibration.pair(size:size,weight:weight)}
 public init(state:State,size:CGFloat=22,weight:Font.Weight = .regular,now:Date = .now){self.state=state;self.size=size;self.weight=weight;self.now=now}
 // Point sizes are independent per role. Images remain native font glyphs, never resizable outlines.
 private var compact:Bool{size<=24}
 // Keep horizontal bearings stable; vertical allowance surrounds the centered geometry.
 public static func layoutWidth(for size:CGFloat)->CGFloat {
  size + (size<=18 ? 4:size<=20 ? 4+(size-18)*0.5:size<=22 ? 5+(size-20)*0.5:size<=32 ? 6:6*size/32)
 }
 /// The gauge diameter and complete symbol height are separate layout dimensions.
 public static func crownHeadroom(for size:CGFloat)->CGFloat{size<=22 ? 1.6:size<=32 ? 1.6+(size-22)*0.04:2*size/32}
 public static func layoutHeight(for size:CGFloat)->CGFloat{size+crownHeadroom(for:size)}
 private var headroom:CGFloat{Self.crownHeadroom(for:size)*inspectionScale}
 private var canvasHeight:CGFloat{Self.layoutHeight(for:size)*inspectionScale}
 private var canvasWidth:CGFloat{Self.layoutWidth(for:size)*inspectionScale}
 // Independent optical stops: a role's proportions are not scaled with the whole icon.
 private func optical(_ a:CGFloat,_ b:CGFloat,_ c:CGFloat,_ display:CGFloat)->CGFloat{
  let value:CGFloat
  if size<=18{value=a}else if size<=20{value=a+(b-a)*(size-18)/2}
  else if size<=22{value=b+(c-b)*(size-20)/2}else if size<=32{value=c+(display-c)*(size-22)/10}
  else{value=display*size/32}
  return value*inspectionScale
 }
 private var nominalLogoFont:CGFloat{state.productID=="openai" ? optical(9.5,11.2,12.0,18.0):optical(11.6,13.0,14.2,17.0)}

