 private var providerPlacement:(name:String,font:CGFloat,point:CGPoint) {
  let micro=compact && ["codex","kimi"].contains(state.productID) ? ".p\(size<=19 ? 18:size<=21 ? 20:22)":""
  let service=ServiceIdentity.find(state.productID)
  let name=service?.existing == false ? service!.symbol(Double(size)):"provider.\(state.productID)\(compact ? ".compact":"")\(micro)"
  let wi=GaugeCalibration.Glyph.weights.firstIndex(of:providerWeight) ?? 3
  let ink:ProviderInk
  if let measured=Self.providerInk[name]?[wi],service?.existing != false && !["codex","kimi"].contains(state.productID) {ink=measured}
  else if let service {
   let m=service.nativeInk(Double(size),wi),x=m[2]/2,y=m[3]/2
   ink=ProviderInk(radius:hypot(x,y),height:m[3],dx:m[0],dy:m[1],outline:[[-x,-y],[x,-y],[x,y],[-x,y]])
  }else{return (name,nominalLogoFont,center)}
  let clearance=state.productID == "openai" ? optical(0.85,0.95,1.05,0.75):optical(0.40,0.45,0.50,0.75)
  let radius=(pair.inner.diameter/2-pair.inner.stroke)*inspectionScale-clearance
  var top=center.y-radius
  if let crown=marks.first(where:{$0.role == .pace}) {
   let cw=GaugeCalibration.Glyph.weights.firstIndex(of:crown.weight) ?? 3
   top=max(top,crown.point.y+CGFloat(Self.overlayInk[crown.name]![cw][1])*crown.font/2+crown.clearance.height)
  }
  let bottom=showPace ? paceBottom-paceInkHeight-optical(0.65,0.70,0.8,1.0):center.y+radius
  func inkCenter(_ font:CGFloat)->CGFloat {
   min(max(center.y,top+font*ink.height/2),bottom-font*ink.height/2)
  }
  // Give a temporary pace notice its own optical space instead of shrinking it
  // into the leftover gap. Identity lifts only during the notice.
  // Fit the native contour, not a circular or rectangular proxy for a flat logo.
  func fits(_ font:CGFloat)->Bool {
   let dy=inkCenter(font)-center.y
   guard font*ink.height <= bottom-top else{return false}
   return ink.outline.allSatisfy{hypot($0[0]*font,$0[1]*font+dy)<=radius}
  }
  var low:CGFloat=0,high=nominalLogoFont
  if fits(high){low=high}else{
   for _ in 0..<16 {let mid=(low+high)/2;if fits(mid){low=mid}else{high=mid}}
  }
  let font=low
  let inkY=inkCenter(font)
  return (name,font,CGPoint(x:center.x-ink.dx*font,y:inkY-ink.dy*font))
 }

 // Tiny open counters fill at heavy weights; thin strokes disappear at light weights.
 // Use the native weight family with a compressed micro range, independently of the rings.
 private func opticalWeight(filled:Bool)->Font.Weight {
  guard compact else{return weight}
  let open:[Font.Weight]=[.regular,.regular,.medium,.semibold,.semibold,.bold,.bold,.heavy,.heavy]
  let solid:[Font.Weight]=[.light,.regular,.regular,.medium,.medium,.semibold,.semibold,.bold,.bold]
  return (filled ? solid:open)[weightIndex]
 }
 private var detailWeight:Font.Weight{opticalWeight(filled:false)}
 private var providerWeight:Font.Weight {
  if ServiceIdentity.find(state.productID)?.existing == false || ["codex","kimi"].contains(state.productID){return weight}
  guard compact else{return weight}
  let open:[Font.Weight]=[.light,.light,.regular,.regular,.regular,.medium,.medium,.semibold,.semibold]
  return state.productID == "gemini" ? opticalWeight(filled:true):open[weightIndex]
 }
 private var center:CGPoint{CGPoint(x:canvasWidth/2,y:canvasHeight/2)}
 private var radius:CGFloat{(pair.outer.diameter-pair.stroke)/2*inspectionScale}
 private var statusFocused:Bool{state.health != .live}
 private var motion:Animation?{reduceMotion ? nil:.smooth(duration:motionDuration)}
 enum Role:String {case pace,warning,authentication,disabled}
 struct Mark:Identifiable {
  var role:Role;var name:String;var point:CGPoint;var font:CGFloat;var weight:Font.Weight;var primary:Bool
  var clearance:CGSize
  var id:String{role.rawValue+"-"+name}
 }
 private var weightIndex:Int{GaugeCalibration.Glyph.weights.firstIndex(of:weight) ?? 3}
 private var effectOptions:SymbolEffectOptions{.speed(0.3/max(0.01,motionDuration))}
 // Optical whitespace is a point-space readability budget, not a percentage of the icon.
 // Narrow punctuation must not excavate the same hole as a wide animal or a diagonal key.
 private func gap(_ name:String,role:Role)->CGSize {
  let heavy=CGFloat(max(0,weightIndex-3))/5
  let weightGap=optical(0.22,0.20,0.17,0.13)*heavy
  let x:CGFloat,y:CGFloat
  switch role {
  case .warning: x=optical(0.56,0.54,0.51,0.56);y=optical(0.92,0.88,0.82,0.78)
  case .authentication:x=optical(0.90,0.88,0.84,0.82);y=optical(0.92,0.90,0.86,0.80)
  case .disabled:x=optical(0.91,0.87,0.81,0.79);y=x
  case .pace:
   x=name == "exclamationmark" ? optical(0.52,0.51,0.49,0.52):optical(0.96,0.91,0.83,0.76)
   y=optical(0.92,0.87,0.81,0.73)
  }
  // At 1×, a subpixel margin can contain no clear display pixel at all.
  // The floor uses logical display density, never the diagnostic zoom factor.
  let pixelFloor=(compact ? 1.0:0.75)/max(1,displayScale)*inspectionScale
  return CGSize(width:max(pixelFloor,x+weightGap*(role == .warning ? 0.5:1)),height:max(pixelFloor,y+weightGap))
 }
 private func glyphFont(_ name:String,role:Role)->CGFloat {
  switch role {
  case .warning:return optical(14.5,15.7,17.0,24.5)
  case .authentication:return optical(13.0,14.2,15.4,22.2)
  case .disabled:return optical(24.0,26.3,28.7,42.0) * 0.6275/0.7775
  case .pace:
   switch name {
   case "hare.fill":return optical(8.5,8.8,9.2,10.0)
   case "tortoise.fill":return optical(8.5,8.9,9.3,10.1)
   case "flame.fill":return optical(8.0,8.5,9.0,10.0)
   case "exclamationmark":return optical(7.0,7.5,7.8,9.0)
   default:return optical(8.5,8.8,9.2,10.0)
   }
  }
 }
 private func mark(_ role:Role,_ name:String,at location:CGPoint,primary:Bool=true)->Mark {
  // Keep the pace glyph's actual native point size. Do not squeeze it into a
  // shared ink-height cap or renormalize its requested weight back to Medium.
  let referenceFont=glyphFont(name,role:role)
  let statusOptics=GaugeStatusOptics.spec(name,size:size,weight:weight)
  let w=statusOptics?.weight ?? opticalWeight(filled:name.hasSuffix(".fill"))
  let wi=GaugeCalibration.Glyph.weights.firstIndex(of:w) ?? 3
  let extent=Self.overlayInk[name]![wi]
  let fallbackFont=role == .pace ? referenceFont:referenceFont * CGFloat(Self.overlayInk[name]![4][1]/extent[1])
  let font=statusOptics.map{$0.font * inspectionScale * (size>22 ? size/22:1)} ?? fallbackFont
  let halfHeight=CGFloat(extent[1])*font/2
  let halfWidth=CGFloat(extent[0])*font/2
  let inset=optical(0.40,0.38,0.35,0.40)
  let limit=canvasHeight
  let horizontalLimit=canvasWidth
  // Native glyph bearings and ink height differ; keep the visible mark inside the symbol.
  let position=CGPoint(x:min(horizontalLimit-inset-halfWidth,max(inset+halfWidth,location.x)),y:min(limit-inset-halfHeight,max(inset+halfHeight,location.y)))
  return Mark(role:role,name:name,point:position,font:font,weight:w,primary:primary,clearance:gap(name,role:role))
 }
 public static let paceNoticeDuration:TimeInterval=4
 public static func paceNoticeIsActive(pace:Pace,eventAt:Date,now:Date)->Bool {
  pace != .normal && now >= eventAt && now.timeIntervalSince(eventAt)<paceNoticeDuration
 }
 private struct NoticeIdentity:Hashable {var pace:Pace;var event:Date?;var duration:Double}
 private var noticeIdentity:NoticeIdentity{.init(pace:state.pace,event:state.paceEventAt,duration:motionDuration)}
 private var showPace:Bool {
  guard !statusFocused,state.pace != .normal else{return false}
  if let event=state.paceEventAt {
   return expiredPaceEvent != event && now >= event && now.timeIntervalSince(event)<GaugeModifierMotion.noticeDuration(motionDuration)
  }
  return automaticNotice
 }
 private var paceBottom:CGFloat{canvasHeight-optical(0.30,0.30,0.35,0.5)}
 private var paceInkHeight:CGFloat {
  switch state.pace {
  case .slow:return optical(5.8,6.2,6.6,8.2)
  case .extreme:return optical(6.8,7.2,7.6,9.2)
  default:return optical(6.4,6.8,7.2,8.8)
  }
 }
 private var paceMarks:[Mark] {
  guard showPace else{return []}
  let name=state.pace == .slow ? "tortoise.fill":state.pace == .fast ? "hare.fill":"flame.fill"
  var notice=mark(.pace,name,at:center)
  let wi=GaugeCalibration.Glyph.weights.firstIndex(of:notice.weight) ?? 3
  let extent=Self.overlayInk[name]![wi]
  // Select the native font by an independent optical ink-height master.
  // No view scaling and no provider-dependent leftover-space cap.
  notice.font=paceInkHeight/extent[1]
  notice.point=CGPoint(x:center.x,y:paceBottom-paceInkHeight/2)
  return [notice]
 }
 private var marks:[Mark]{[]}
 private var problems:[Mark]{
  guard statusFocused else{return []}
  let role:Role = state.health == .authentication ? .authentication:[.offline,.disabled].contains(state.health) ? .disabled:.warning
  let name:String
  switch state.health {
  case .outage:name="bolt.horizontal.fill"
  case .unknown:name="questionmark"
  case .stale:name="clock"
  case .paused:name="pause.fill"
  case .authentication:name="key.fill"
  default:name="circle.slash"
  }
  return [mark(role,name,at:center)]
 }
 private func point(_ degrees:CGFloat)->CGPoint{let a=degrees * .pi/180;return CGPoint(x:center.x+radius*cos(a),y:center.y+radius*sin(a))}
 private func layerTransition(_ mark:Mark)->AnyTransition {
  GaugeModifierMotion.transition(mark.name,scale:inspectionScale,duration:motionDuration,reduceMotion:reduceMotion)
 }
 private func modifierEvent(_ mark:Mark)->Date? {
  ["hare.fill","tortoise.fill","flame.fill"].contains(mark.name) ? state.paceEventAt:state.healthEventAt
 }
 private func modifierIdentity(_ mark:Mark)->String {mark.id+"-"+String(modifierEvent(mark)?.timeIntervalSince1970 ?? 0)}
 private func image(_ mark:Mark)->some View{
  NativeModifierSymbol(name:mark.name,font:mark.font,weight:mark.weight,
   angle:0,
   replay:modifierEvent(mark))
 }
 private func decorated(_ list:[Mark])->some View{
  ZStack{
   ForEach(list){mark in
    image(mark).id(modifierIdentity(mark)).foregroundStyle(mark.primary ? Color.primary:Color.primary.opacity(compact ? 0.8:0.65))
     .position(mark.point).transition(layerTransition(mark))
   }
  }.frame(width:canvasWidth,height:canvasHeight)
 }
 /// Foreground and knockout share glyph identity, motion preset, speed, and insertion/removal.
 /// Elliptical clearance follows native contours; it never defines gauge progress.
 private func clearanceMask(_ list:[Mark],logo:Bool=false)->some View{
  ZStack{
   Color.white
   ForEach(list){mark in
    NativeSymbolClearance(gap:logo ? CGSize(width:0.25*inspectionScale,height:0.25*inspectionScale):mark.clearance){
     image(mark).position(mark.point).frame(width:canvasWidth,height:canvasHeight)
    }.id(modifierIdentity(mark)).transition(layerTransition(mark)).blendMode(.darken)
   }
  }.frame(width:canvasWidth,height:canvasHeight).compositingGroup().luminanceToAlpha()
 }
 private var countdowns:some View {
  NativeResetPair(weekly:state.weeklyReset,fiveHour:state.fiveHourReset,now:now,size:size,weight:weight)
   .symbolRenderingMode(.hierarchical).foregroundStyle(statusFocused ? AnyShapeStyle(.tertiary):AnyShapeStyle(.secondary))
 }
 @ViewBuilder public var body:some View{
  if variation == .laurel || state.windows != nil {LaurelGauge(state:state,size:size,weight:weight,now:now)}else{concentricBody}
 }
 private var concentricBody:some View{
  ZStack{
   ZStack{
    ZStack {
    NativeGaugePair(weekly:state.weeklyUsed,fiveHour:state.fiveHourUsed,size:size,weight:weight)
      .foregroundStyle(statusFocused ? AnyShapeStyle(.secondary):AnyShapeStyle(.primary))
      .frame(width:canvasWidth,height:canvasHeight).mask(clearanceMask(paceMarks))
     
    }.mask(clearanceMask(marks))
    if !showPace {countdowns.transition(.opacity)}
     decorated(paceMarks)
    decorated(marks)
   }.mask(clearanceMask(problems))
    Image(providerPlacement.name)
     .font(.system(size:providerPlacement.font,weight:providerWeight)).imageScale(.small)
     // Respect the custom SF Symbol's native tertiary layer role.
     .symbolRenderingMode(statusFocused ? .palette:.hierarchical)
     .foregroundStyle(HierarchicalShapeStyle.primary,HierarchicalShapeStyle.secondary,statusFocused ? AnyShapeStyle(.secondary):AnyShapeStyle(.tertiary))
     .contentTransition(.symbolEffect(.replace.offUp.wholeSymbol,options:effectOptions))
     .symbolEffectsRemoved(reduceMotion)
     .position(providerPlacement.point)
     .mask(clearanceMask(problems,logo:true))
   decorated(problems)
  }.frame(width:canvasWidth,height:canvasHeight)
   .onGeometryChange(for:CGPoint.self) { proxy in
    proxy.frame(in:.global).origin
   } action: { pixelOrigin=$0 }
   .animation(motion,value:state)
    .animation(motion,value:showPace)
   .task(id:noticeIdentity) {
     automaticNotice=false
     guard state.pace != .normal else{return}
     let event=state.paceEventAt
     let remaining=event.map{max(0,GaugeModifierMotion.noticeDuration(motionDuration)-Date.now.timeIntervalSince($0))} ?? GaugeModifierMotion.noticeDuration(motionDuration)
     if event == nil {automaticNotice=true}
     do {try await Task.sleep(for:.seconds(remaining))} catch {return}
     automaticNotice=false
     if let event {expiredPaceEvent=event}
    }
    .accessibilityElement(children:.ignore)
   .accessibilityLabel(state.accessibilityDescription.isEmpty ? accessibility:state.accessibilityDescription)
 }
