/// One motion vocabulary for foreground glyphs and their contour-following knockout.
/// All artwork remains native SF Symbols. Travel is SwiftUI layout motion; articulation
/// and draw/bounce/breathe are supplied by the system symbol engine.
@MainActor enum GaugeModifierMotion {
 static func tempo(_ duration:Double)->Double {max(0.1,duration/0.3)}
 static func noticeDuration(_ duration:Double)->Double {ComputeGauge.paceNoticeDuration*max(1,tempo(duration))}
 static func transition(_ name:String,scale:CGFloat=1,vertical:Bool=false,duration:Double=0.3,reduceMotion:Bool=false)->AnyTransition {
  if reduceMotion{return .opacity.animation(.easeOut(duration:0.12))}
  let t=tempo(duration),speed=1/t
  switch name {
  case "circle.slash":
   return AnyTransition(SymbolEffectTransition(effect:.drawOn.wholeSymbol,options:.speed(speed*1.4)))
  case "tortoise.fill","hare.fill":
   let slow=name=="tortoise.fill",travel:CGFloat=(slow ? 3:5)*scale
   let arrival=AnyTransition.opacity.combined(with:.offset(x:vertical ? 0:-travel,y:vertical ? travel:0))
   let departure=AnyTransition.opacity.combined(with:.offset(x:vertical ? 0:travel,y:vertical ? -travel:0))
   return .asymmetric(insertion:arrival.animation(.easeOut(duration:(slow ? 1.1:0.24)*t)),removal:departure.animation(.easeIn(duration:(slow ? 0.7:0.18)*t)))
  case "bolt.horizontal.fill":
   return AnyTransition(SymbolEffectTransition(effect:.appear.up.wholeSymbol,options:.speed(speed*0.85)))
  case "questionmark":
   return AnyTransition(SymbolEffectTransition(effect:.appear.byLayer,options:.speed(speed)))
  case "exclamationmark":
   return AnyTransition(SymbolEffectTransition(effect:.appear.down.byLayer,options:.speed(speed*1.6)))
  case "flame.fill":
   return AnyTransition(SymbolEffectTransition(effect:.appear.up.byLayer,options:.speed(speed*1.35)))
  case "key.fill":
   return AnyTransition(SymbolEffectTransition(effect:.drawOn.byLayer,options:.speed(speed*1.2)))
  case "pause.fill":
   return AnyTransition(SymbolEffectTransition(effect:.appear.byLayer,options:.speed(speed*1.4)))
  default:
   return AnyTransition(SymbolEffectTransition(effect:.appear.wholeSymbol,options:.speed(speed)))
  }
 }
}

struct NativeModifierSymbol:View {
 var name:String
 var font:CGFloat
 var weight:Font.Weight
 var angle:Double=0
 var replay:Date?=nil
 @Environment(\.symbolMotionDuration) private var duration
 @Environment(\.accessibilityReduceMotion) private var reduceMotion
 @State private var tick=0
 private var speed:Double {1/GaugeModifierMotion.tempo(duration)}
 @ViewBuilder private var glyph:some View {
  if name == "circle.slash" {
   // Use the system slash layer and its directional draw annotations. The
   // circle is transparent; the primary slash inherits foreground/knockout ink.
   Image(systemName:name).font(.system(size:font,weight:weight)).imageScale(.small)
    .symbolRenderingMode(.palette).foregroundStyle(HierarchicalShapeStyle.primary,Color.clear)
  }else{
   Image(systemName:name).font(.system(size:font,weight:weight)).imageScale(.small)
    .symbolRenderingMode(.monochrome)
  }
 }
 @ViewBuilder private var animated:some View {
  switch name {
  case "exclamationmark":
   glyph.symbolEffect(.bounce.down.byLayer,options:.speed(1.6*speed),value:tick)
  case "tortoise.fill":
   glyph.symbolEffect(.wiggle.custom(angle:4).wholeSymbol,options:.speed(0.65*speed).repeat(2),value:tick)
  case "hare.fill":
   glyph.symbolEffect(.bounce.up.wholeSymbol,options:.speed(2.2*speed).repeat(2),value:tick)
  case "flame.fill":
   glyph.symbolEffect(.breathe.pulse.byLayer,options:.speed(1.8*speed).repeat(2),value:tick)
    .symbolEffect(.wiggle.custom(angle:3).byLayer,options:.speed(1.6*speed).repeat(2),value:tick)
  case "key.fill":
   glyph.symbolEffect(.wiggle.clockwise.wholeSymbol,options:.speed(1.25*speed),value:tick)
  case "bolt.horizontal.fill":
   glyph.symbolEffect(.bounce.up.wholeSymbol,options:.speed(1.4*speed),value:tick)
    .symbolEffect(.pulse.wholeSymbol,options:.speed(1.8*speed).repeat(2),value:tick)
  case "questionmark":
   glyph.symbolEffect(.wiggle.custom(angle:6).wholeSymbol,options:.speed(speed),value:tick)
  case "clock":
   glyph.symbolEffect(.pulse.byLayer,options:.speed(0.8*speed),value:tick)
  default:glyph
  }
 }
 var body:some View {
  animated.rotationEffect(.degrees(angle)).symbolEffectsRemoved(reduceMotion)
   .task(id:replay) {
    guard !reduceMotion else{return}
    // Trigger after insertion, when the native symbol layer is mounted. The
    // foreground and knockout copies enter in the same SwiftUI transaction.
    // A yield can run before the first render commit and swallow the effect.
    // Start after two display frames, once the native symbol layer is mounted.
    do{try await Task.sleep(for:.milliseconds(40))}catch{return}
    guard !Task.isCancelled else{return}
    tick += 1
   }
 }
}

/// Optical ink targets in display points, independent for each status glyph.
/// Heavy native slash masters retain a readable stroke without stretching paths.
@MainActor enum GaugeStatusOptics {
 static let ink:[String:[[Double]]] = ["circle.slash":[[0.72,0.72,-0.00125,-0.00125],[0.73,0.7325,-0.00125,0],[0.7525,0.7525,0,0],[0.7675,0.7675,0,0],[0.7775,0.7775,-0.00125,-0.00125],[0.785,0.785,-0.00125,0],[0.7925,0.7925,0,0],[0.805,0.805,-0.00125,-0.00125],[0.8175,0.8175,-0.00125,0]],"bolt.horizontal.fill":[[0.98,0.425,0,-0.00125],[0.9975,0.44,0,0],[1.0425,0.465,0,-0.00125],[1.07,0.4825,0,0],[1.0775,0.4925,0,0],[1.08,0.4975,-0.00125,0],[1.085,0.505,0.00125,0],[1.0925,0.5175,-0.00125,0],[1.1,0.5275,0,-0.00125]],"questionmark":[[0.3725,0.7175,-0.00125,-0.00125],[0.385,0.72,-0.00125,-0.00125],[0.4075,0.7275,-0.00125,0],[0.425,0.7325,-0.00125,0],[0.44,0.7325,-0.00125,0],[0.4525,0.73,0,-0.00125],[0.4675,0.73,0,-0.00125],[0.4875,0.73,-0.00125,-0.00125],[0.5075,0.73,-0.00125,-0.00125]]]
 static func spec(_ name:String,size:CGFloat,weight:Font.Weight,wide:Bool=false)->(font:CGFloat,weight:Font.Weight)? {
  guard let rows=ink[name] else{return nil}
  let i=GaugeCalibration.Glyph.weights.firstIndex(of:weight) ?? 3
  let weights = name == "circle.slash" ? [6,6,7,8,8,8,8,8,8]:[4,4,5,5,6,6,7,7,8]
  let selected=weights[i]
  if name == "circle.slash",wide {
   return (size<=18 ? 27:size<=20 ? 28:29,GaugeCalibration.Glyph.weights[selected])
  }
  let target:CGFloat
  switch name {
  case "circle.slash":target=size<=18 ? 16.5:size<=20 ? 17.5:18.5
  case "bolt.horizontal.fill":target=size<=18 ? 13:size<=20 ? 14:15
  default:target=size<=18 ? 12:size<=20 ? 13:14
  }
  let dimension=rows[selected][name == "bolt.horizontal.fill" ? 0:1]
  return (target/CGFloat(dimension),GaugeCalibration.Glyph.weights[selected])
 }
}
